/// Octave's mod(x, y) for finite doubles as doodson takes it: x - floor(x/y) y, 0 when y is not whole and x/y is within
/// one relative eps of a whole number, the result with the sign of y.
/// - x: real[1] (passed a plain number)
/// - y: real[1] (passed a plain number)
/// - returns r: real[1] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn ocean_mod(x: f64, y: f64) -> f64 {
    let mut r: f64 = 0.0;
    if (y == 0.0) {
        r = x;
    } else {
        let mut q: f64 = (x / y);
        let mut ny: f64 = f64::floor((y + 0.5));
        let mut nq: f64 = f64::floor((q + 0.5));
        if ((ny != y) && (rt::fabs(((q - nq) / nq)) < 2.220446049250313e-16)) {
            r = 0.0;
        } else {
            r = (x - (y * f64::floor(q)));
        }
        if (((x != y) && (r != 0.0)) && ((r < 0.0) != (y < 0.0))) {
            r = (r + y);
        }
    }
    r
}

